insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:genie-informatique-developpement')::uuid, 'genie-informatique-developpement', 'Génie informatique et développement logiciel', 'Concevoir et développer des applications web, mobiles et métiers.', 'Conception, développement, test et maintenance d''applications logicielles : sites et applications web, applications mobiles, API et logiciels métiers utilisés par les entreprises et les administrations.', array['Git', 'VS Code', 'Node.js', 'Python', 'PostgreSQL', 'React', 'Docker', 'Postman']::text[], array['Meta Front-End Developer (Coursera)', 'Oracle Certified Associate Java', 'AWS Certified Developer – Associate']::text[], array['Application web complète avec authentification', 'API REST documentée', 'Application mobile', 'Contribution open source']::text[], 'Débutant : réalise des fonctionnalités simples guidées. Intermédiaire : livre une application complète testée. Avancé : conçoit l''architecture et encadre. Expert : définit les standards techniques d''une organisation.', 'code', 1) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:genie-logiciel-qualite')::uuid, 'genie-logiciel-qualite', 'Génie logiciel, architecture et assurance qualité', 'Architecturer des logiciels fiables et garantir leur qualité.', 'Méthodes et pratiques permettant de concevoir des logiciels maintenables : architecture, conception orientée objet, tests automatisés, intégration continue, revue de code et assurance qualité.', array['Jira', 'SonarQube', 'Jest / Vitest', 'Playwright', 'Selenium', 'GitHub Actions', 'UML / C4']::text[], array['ISTQB Foundation Level', 'Professional Scrum Master I', 'iSAQB CPSA-F']::text[], array['Plan de tests et campagne automatisée', 'Refactorisation documentée d''un code existant', 'Pipeline CI/CD', 'Dossier d''architecture']::text[], 'Progression de l''application de tests écrits par d''autres vers la définition de la stratégie qualité et de l''architecture d''un produit.', 'layers', 2) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:reseaux-telecommunications')::uuid, 'reseaux-telecommunications', 'Réseaux et télécommunications', 'Concevoir, déployer et exploiter les réseaux d''entreprise et d''opérateurs.', 'Conception, installation, configuration et supervision des réseaux locaux et étendus, des réseaux sans fil et des infrastructures de télécommunications (fibre, radio, mobile).', array['Cisco Packet Tracer', 'GNS3', 'Wireshark', 'MikroTik RouterOS', 'Zabbix', 'Ubiquiti UniFi']::text[], array['Cisco CCNA', 'MikroTik MTCNA', 'CompTIA Network+', 'Huawei HCIA-Datacom']::text[], array['Maquette réseau d''entreprise avec VLAN et routage', 'Déploiement Wi-Fi d''un site', 'Supervision d''un réseau', 'Étude de couverture radio']::text[], 'De la configuration d''équipements guidée à la conception d''architectures réseau multi-sites sécurisées.', 'network', 3) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:cybersecurite')::uuid, 'cybersecurite', 'Cybersécurité et sécurité des systèmes', 'Protéger les systèmes, les données et les utilisateurs.', 'Protection des systèmes d''information : sécurité des réseaux et des applications, gestion des identités, détection et réponse aux incidents, tests d''intrusion autorisés et conformité.', array['Wireshark', 'Nmap', 'Burp Suite', 'Wazuh', 'Kali Linux', 'Splunk / Elastic SIEM', 'OpenVAS']::text[], array['CompTIA Security+', 'Cisco CyberOps Associate', 'EC-Council CEH', 'ISC2 Certified in Cybersecurity (CC)']::text[], array['Audit de sécurité autorisé d''un environnement de test', 'Déploiement d''un SIEM', 'Plan de réponse à incident', 'Participation à des CTF']::text[], 'De l''application de bonnes pratiques d''hygiène informatique à la conduite d''audits et de programmes de sécurité.', 'shield', 4) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:systemes-cloud')::uuid, 'systemes-cloud', 'Systèmes, infrastructures numériques et cloud', 'Administrer serveurs, virtualisation et services cloud.', 'Administration des systèmes Linux et Windows, virtualisation, conteneurs, services d''infrastructure (annuaire, messagerie, sauvegarde) et plateformes cloud publiques ou privées.', array['Linux (Ubuntu, Debian, RHEL)', 'Windows Server', 'Proxmox / VMware', 'Docker', 'Kubernetes', 'Terraform', 'Ansible', 'AWS / Azure']::text[], array['CompTIA Linux+', 'Microsoft Azure Fundamentals (AZ-900)', 'AWS Certified Cloud Practitioner', 'Red Hat RHCSA']::text[], array['Infrastructure virtualisée documentée', 'Déploiement conteneurisé d''une application', 'Plan de sauvegarde et restauration testé', 'Infrastructure as Code']::text[], 'De l''exploitation de serveurs à la conception d''infrastructures résilientes et automatisées.', 'server', 5) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:intelligence-artificielle-donnees')::uuid, 'intelligence-artificielle-donnees', 'Intelligence artificielle et science des données', 'Exploiter les données et construire des modèles d''apprentissage automatique.', 'Collecte, préparation, analyse et visualisation de données ; statistiques ; apprentissage automatique et profond ; mise en production responsable de modèles d''IA.', array['Python', 'pandas', 'scikit-learn', 'Jupyter', 'SQL', 'Power BI', 'PyTorch / TensorFlow', 'MLflow']::text[], array['Google Data Analytics', 'Microsoft Power BI Data Analyst (PL-300)', 'TensorFlow Developer', 'IBM Data Science']::text[], array['Analyse exploratoire d''un jeu de données public', 'Tableau de bord décisionnel', 'Modèle prédictif évalué', 'Application d''IA déployée']::text[], 'De l''analyse descriptive à la conception et au déploiement responsable de modèles d''IA.', 'brain', 6) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:electronique-systemes-embarques')::uuid, 'electronique-systemes-embarques', 'Électronique et systèmes embarqués', 'Concevoir des cartes électroniques et programmer des microcontrôleurs.', 'Conception de circuits analogiques et numériques, réalisation de cartes électroniques, programmation de microcontrôleurs et de systèmes temps réel.', array['KiCad', 'Proteus', 'STM32CubeIDE', 'Arduino IDE', 'Oscilloscope', 'Multimètre', 'FreeRTOS']::text[], array['IPC-A-610 (assemblage électronique)', 'Certifications Arm / STMicroelectronics (formations constructeur)']::text[], array['Conception d''une carte électronique (schéma + PCB)', 'Système embarqué à microcontrôleur', 'Banc de mesure', 'Prototype alimenté par batterie']::text[], 'Du montage de circuits sur plaque d''essai à la conception de systèmes embarqués industrialisables.', 'cpu', 7) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:electrotechnique-genie-electrique')::uuid, 'electrotechnique-genie-electrique', 'Électrotechnique et génie électrique', 'Concevoir, installer et maintenir les installations électriques.', 'Installations électriques basse et moyenne tension, machines électriques, distribution d''énergie, protection des personnes et des biens, maintenance électrique.', array['Caneco BT', 'AutoCAD Electrical', 'EPLAN', 'Multimètre / pince ampèremétrique', 'Mesureur d''isolement', 'Dialux']::text[], array['Habilitation électrique (B1V, BR, BC, H0…)', 'Formations constructeurs (Schneider, ABB)']::text[], array['Dimensionnement d''une installation BT', 'Schéma d''armoire électrique', 'Diagnostic énergétique', 'Mise en conformité d''une installation']::text[], 'De l''intervention encadrée à la conception et à la direction de projets électriques.', 'zap', 8) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:automatisation-industrielle')::uuid, 'automatisation-industrielle', 'Automatisation industrielle et contrôle-commande', 'Programmer automates et systèmes de supervision industriels.', 'Automates programmables (API), capteurs et actionneurs, supervision SCADA, réseaux industriels, régulation et contrôle-commande des procédés.', array['TIA Portal (Siemens)', 'Schneider EcoStruxure / Unity Pro', 'Codesys', 'Ignition / WinCC', 'Modbus', 'Profinet']::text[], array['Siemens TIA Portal (formations constructeur)', 'ISA CCST (Certified Control Systems Technician)']::text[], array['Programme automate d''une machine', 'Écran de supervision', 'Boucle de régulation PID', 'Rétrofit d''une installation']::text[], 'De la modification de programmes existants à la conception de systèmes de contrôle-commande complets.', 'settings', 9) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:robotique-mecatronique')::uuid, 'robotique-mecatronique', 'Robotique et mécatronique', 'Intégrer mécanique, électronique et informatique dans des systèmes robotisés.', 'Conception et intégration de systèmes mécatroniques et robotisés : modélisation, motorisation, commande, perception et programmation de robots industriels et mobiles.', array['ROS 2', 'SolidWorks / Fusion 360', 'MATLAB / Simulink', 'Gazebo', 'Arduino / Raspberry Pi', 'Robots industriels (ABB, FANUC, KUKA)']::text[], array['Formations constructeurs de robots industriels', 'Certifications SolidWorks (CSWA)']::text[], array['Robot mobile autonome', 'Bras robotisé commandé', 'Cellule robotisée simulée', 'Prototype mécatronique']::text[], 'De l''assemblage et la programmation de robots pédagogiques à la conception de systèmes robotisés industriels.', 'bot', 10) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:internet-des-objets')::uuid, 'internet-des-objets', 'Internet des objets (IoT)', 'Connecter capteurs et objets pour collecter et exploiter des données.', 'Conception de solutions connectées de bout en bout : capteurs, objets communicants, réseaux bas débit (LoRaWAN, NB-IoT), passerelles, plateformes et applications de visualisation.', array['ESP32', 'Raspberry Pi', 'MQTT (Mosquitto)', 'LoRaWAN / The Things Stack', 'Node-RED', 'InfluxDB / Grafana']::text[], array['Cisco IoT Fundamentals (NetAcad)', 'LoRaWAN Fundamentals (LoRa Alliance)']::text[], array['Station de mesure connectée (qualité de l''eau, météo)', 'Suivi d''actifs par LoRaWAN', 'Compteur énergétique connecté', 'Tableau de bord temps réel']::text[], 'Du prototype connecté à la solution IoT sécurisée déployée à grande échelle.', 'radio', 11) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:genie-civil-construction')::uuid, 'genie-civil-construction', 'Génie civil et construction', 'Concevoir, calculer et réaliser bâtiments et infrastructures.', 'Études et réalisation de bâtiments, routes, ouvrages d''art et réseaux : topographie, calcul de structures, matériaux, géotechnique, conduite et suivi de chantier.', array['AutoCAD', 'Revit', 'Robot Structural Analysis', 'Covadis', 'Station totale / GNSS', 'MS Project']::text[], array['Autodesk Certified Professional (AutoCAD, Revit)', 'Formations en sécurité de chantier']::text[], array['Note de calcul d''un bâtiment R+2', 'Plans d''exécution', 'Métré et devis quantitatif estimatif', 'Rapport de suivi de chantier']::text[], 'Du dessin et du métré à la conception et à la direction de projets de construction.', 'building', 12) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:genie-mecanique-maintenance')::uuid, 'genie-mecanique-maintenance', 'Génie mécanique et maintenance industrielle', 'Concevoir des systèmes mécaniques et assurer leur fiabilité.', 'Conception mécanique, fabrication, maintenance des équipements industriels et miniers, fiabilité, hydraulique et pneumatique, gestion de la maintenance assistée par ordinateur.', array['SolidWorks', 'AutoCAD Mechanical', 'GMAO (SAP PM, Maximo, CMMS)', 'Analyseur de vibrations', 'Thermographie']::text[], array['Certifications SolidWorks (CSWA / CSWP)', 'Analyse vibratoire (ISO 18436-2)', 'Lubrification (ICML)']::text[], array['Conception d''un mécanisme avec mise en plan', 'Plan de maintenance préventive', 'Analyse de défaillance (AMDEC)', 'Rapport d''analyse vibratoire']::text[], 'De l''intervention de maintenance à la conception mécanique et la stratégie de fiabilité.', 'wrench', 13) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:energies-renouvelables')::uuid, 'energies-renouvelables', 'Énergies renouvelables et efficacité énergétique', 'Dimensionner et maintenir des systèmes solaires et des solutions d''efficacité énergétique.', 'Production d''énergie renouvelable (solaire photovoltaïque, hydroélectricité, éolien, biomasse), mini-réseaux et électrification rurale, stockage, audits et efficacité énergétique.', array['PVsyst', 'HOMER Pro', 'RETScreen', 'SketchUp / Helioscope', 'Pinces et analyseurs de réseau', 'Logiciels de supervision d''onduleurs']::text[], array['NABCEP PV Associate', 'Certified Energy Manager (AEE)', 'Formations constructeurs d''onduleurs']::text[], array['Dimensionnement d''un système solaire autonome', 'Étude d''un mini-réseau villageois', 'Audit énergétique d''un bâtiment', 'Suivi de performance d''une centrale']::text[], 'De l''installation de systèmes solaires domestiques à la conception de centrales et de mini-réseaux.', 'sun', 14) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.engineering_domains (id, slug, name, short_description, description, tools, certifications, project_types, progression_criteria, icon, position) values (md5('domain:genie-industriel-production')::uuid, 'genie-industriel-production', 'Génie industriel et gestion de production', 'Organiser et améliorer la production, la qualité et la logistique.', 'Organisation et pilotage des systèmes de production : planification, amélioration continue (Lean, Six Sigma), qualité, logistique et chaîne d''approvisionnement, santé-sécurité.', array['Excel avancé', 'ERP (SAP, Odoo)', 'Minitab', 'MS Project', 'Outils Lean (VSM, 5S, Kanban)']::text[], array['Lean Six Sigma Yellow / Green Belt', 'APICS CPIM', 'ISO 9001 Auditeur interne', 'ISO 45001']::text[], array['Cartographie de flux (VSM) et plan d''amélioration', 'Chantier 5S documenté', 'Plan de production', 'Analyse statistique de la qualité']::text[], 'De la participation à des actions d''amélioration à la direction de la performance industrielle.', 'factory', 15) on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, tools = excluded.tools, certifications = excluded.certifications, project_types = excluded.project_types, progression_criteria = excluded.progression_criteria, icon = excluded.icon, position = excluded.position;
insert into public.skills (id, domain_id, slug, name, category, tier, level_criteria, aliases) values (md5('skill:communication-professionnelle')::uuid, null, 'communication-professionnelle', 'Communication professionnelle', 'transversale', 'fondamentale', '{"debutant":"Transmet une information simple de façon claire à l''oral et à l''écrit.","intermediaire":"Adapte son message à l''interlocuteur (technicien, client, responsable) et rédige des courriels structurés.","avance":"Présente un projet technique devant un public non spécialiste et répond aux objections.","expert":"Anime des réunions à enjeux, négocie et représente l''organisation auprès de partenaires."}'::jsonb, array[]::text[]) on conflict (slug) do update set name = excluded.name, category = excluded.category, tier = excluded.tier, level_criteria = excluded.level_criteria, aliases = excluded.aliases, domain_id = excluded.domain_id;
insert into public.skills (id, domain_id, slug, name, category, tier, level_criteria, aliases) values (md5('skill:travail-equipe')::uuid, null, 'travail-equipe', 'Travail en équipe', 'transversale', 'fondamentale', '{"debutant":"Réalise les tâches confiées au sein d''une équipe et respecte les délais.","intermediaire":"Coordonne son travail avec d''autres membres et partage l''information utile.","avance":"Facilite la collaboration, aide les nouveaux membres et gère des désaccords.","expert":"Encadre une équipe pluridisciplinaire et développe les compétences de ses membres."}'::jsonb, array[]::text[]) on conflict (slug) do update set name = excluded.name, category = excluded.category, tier = excluded.tier, level_criteria = excluded.level_criteria, aliases = excluded.aliases, domain_id = excluded.domain_id;
insert into public.skills (id, domain_id, slug, name, category, tier, level_criteria, aliases) values (md5('skill:resolution-problemes')::uuid, null, 'resolution-problemes', 'Résolution de problèmes', 'transversale', 'fondamentale', '{"debutant":"Identifie un problème et applique une procédure connue pour le résoudre.","intermediaire":"Analyse les causes d''un incident et propose plusieurs solutions argumentées.","avance":"Résout des problèmes complexes non documentés en structurant une démarche (diagnostic, hypothèses, tests).","expert":"Conçoit des méthodes de résolution réutilisables et forme les autres à les appliquer."}'::jsonb, array[]::text[]) on conflict (slug) do update set name = excluded.name, category = excluded.category, tier = excluded.tier, level_criteria = excluded.level_criteria, aliases = excluded.aliases, domain_id = excluded.domain_id;
insert into public.skills (id, domain_id, slug, name, category, tier, level_criteria, aliases) values (md5('skill:gestion-projet')::uuid, null, 'gestion-projet', 'Gestion de projet', 'transversale', 'fondamentale', '{"debutant":"Planifie ses propres tâches et suit leur avancement.","intermediaire":"Établit un planning, identifie les dépendances et rend compte de l''avancement d''un petit projet.","avance":"Pilote un projet (budget, risques, parties prenantes) et prend des décisions d''arbitrage.","expert":"Dirige un portefeuille de projets et met en place des méthodes de gestion adaptées."}'::jsonb, array['gestion de projets', 'project management', 'agile', 'scrum']::text[]) on conflict (slug) do update set name = excluded.name, category = excluded.category, tier = excluded.tier, level_criteria = excluded.level_criteria, aliases = excluded.aliases, domain_id = excluded.domain_id;
insert into public.skills (id, domain_id, slug, name, category, tier, level_criteria, aliases) values (md5('skill:anglais-technique')::uuid, null, 'anglais-technique', 'Anglais technique', 'transversale', 'fondamentale', '{"debutant":"Comprend une documentation technique simple avec l''aide d''outils.","intermediaire":"Lit une documentation technique en autonomie et rédige des messages courts.","avance":"Échange oralement avec des interlocuteurs anglophones sur des sujets techniques.","expert":"Rédige et présente des documents techniques complexes en anglais."}'::jsonb, array['anglais', 'english']::text[]) on conflict (slug) do update set name = excluded.name, category = excluded.category, tier = excluded.tier, level_criteria = excluded.level_criteria, aliases = excluded.aliases, domain_id = excluded.domain_id;
insert into public.skills (id, domain_id, slug, name, category, tier, level_criteria, aliases) values (md5('skill:redaction-technique')::uuid, null, 'redaction-technique', 'Rédaction technique', 'transversale', 'fondamentale', '{"debutant":"Rédige un compte rendu factuel d''une intervention.","intermediaire":"Produit une documentation utilisable par un tiers (procédure, notice).","avance":"Rédige des spécifications ou rapports techniques structurés et vérifiables.","expert":"Définit les standards documentaires d''une équipe et relit les documents critiques."}'::jsonb, array[]::text[]) on conflict (slug) do update set name = excluded.name, category = excluded.category, tier = excluded.tier, level_criteria = excluded.level_criteria, aliases = excluded.aliases, domain_id = excluded.domain_id;
